{
  "name": "@runkids/figlens",
  "mcpName": "io.github.runkids/figlens",
  "version": "0.14.4",
  "description": "Give your coding agent the design details to build, compare and follow changes from a saved Figma .fig: layout, text, variables, assets, reference renders, screenshot comparison and revision diffs. Offline: no Dev Mode seat, login or API quota. Pi, OpenCode, OMP, CLI and MCP.",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/runkids/figlens.git"
  },
  "homepage": "https://figlens.runkids.cc",
  "keywords": [
    "figma",
    "fig",
    "design-to-code",
    "cli",
    "ai",
    "mcp",
    "mcp-server",
    "figma-mcp",
    "figma-to-code",
    "offline",
    "opencode",
    "omp",
    "pi-package"
  ],
  "bin": {
    "figlens": "bin/figlens.js"
  },
  "files": [
    "bin/",
    "pull/",
    "target.js",
    "pi/",
    "skills/",
    "opencode/",
    "omp/",
    ".mcp.json"
  ],
  "pi": {
    "extensions": [
      "./pi/index.ts"
    ],
    "skills": [
      "./skills"
    ],
    "image": "https://raw.githubusercontent.com/runkids/figlens/v0.10.1/assets/taskflow-demo-poster.jpg",
    "video": "https://raw.githubusercontent.com/runkids/figlens/v0.10.1/assets/taskflow-demo.mp4"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "^1.3.0",
    "@earendil-works/pi-tui": "*",
    "typebox": "*",
    "@oh-my-pi/pi-coding-agent": "^18.13.2",
    "@oh-my-pi/pi-tui": "*",
    "@opencode/plugin": "2.2.0",
    "playwright-core": ">=1.40.0"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    },
    "@earendil-works/pi-tui": {
      "optional": true
    },
    "typebox": {
      "optional": true
    },
    "@oh-my-pi/pi-coding-agent": {
      "optional": true
    },
    "@oh-my-pi/pi-tui": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    },
    "playwright-core": {
      "optional": true
    }
  },
  "engines": {
    "node": ">=18"
  },
  "os": [
    "darwin",
    "linux",
    "win32"
  ],
  "cpu": [
    "arm64",
    "x64"
  ],
  "omp": {
    "extensions": [
      "./omp/index.ts"
    ],
    "skills": [
      "./skills"
    ]
  },
  "exports": {
    ".": "./opencode/index.mjs",
    "./tui": "./opencode/tui.mjs",
    "./rpc": "./opencode/rpc.mjs",
    "./package.json": "./package.json"
  }
}
